const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',sparkles:'<path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6Z"/><path d="m20 2 .7 1.3L22 4l-1.3.7L20 6l-.7-1.3L18 4l1.3-.7Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',leaf:'<path d="M20 3C8 2 1 9 5 16s16 4 15-13Z"/><path d="m3 21 12-12"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m9 21 2-7 3 3v5M5 13l4-3 3-3 3 5 4 1M11 14l1-7"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chat:'<path d="M21 11.5a9 9 0 0 1-9.5 9A10 10 0 0 1 7 19.4L2 21l1.6-5A10 10 0 0 1 2.5 11.5a9 9 0 1 1 18.5 0Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',camera:'<path d="M3 6h4l2-3h6l2 3h4v15H3Z"/><circle cx="12" cy="13" r="4"/>',check:'<path d="m5 12 4 4L19 6"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3 6 0 1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z"/>',volume:'<path d="M11 4 5 9H2v6h3l6 5ZM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',shop:'<path d="M3 9 5 3h14l2 6M3 9v3a3 3 0 0 0 6 0 3 3 0 0 0 6 0 3 3 0 0 0 6 0V9ZM5 15v6h14v-6M10 21v-5h4v5"/>',chart:'<path d="M4 3v18h17M8 16v-5m5 5V6m5 10v-7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const I=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.sparkles}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('ko-KR')+'원';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const shops=[{id:'bake',name:'오후의 빵집',handle:'afternoon.bread',image:'croissant',desc:'갓 구운 빵이 있는 작은 골목',address:'성수동 가상 골목 12',lat:37.5445,lng:127.0433},{id:'cafe',name:'모퉁이 커피',handle:'corner.coffee',image:'coffee',desc:'잠깐 쉬어 가는 커피 한 잔',address:'성수동 가상 골목 18',lat:37.5438,lng:127.0421},{id:'rice',name:'소담한 식탁',handle:'sodam.table',image:'rice',desc:'매일 정성껏 짓는 한 끼',address:'성수동 가상 골목 24',lat:37.5441,lng:127.0407}];
const seed=[{id:1,shop:'bake',name:'딸기 크루아상',price:4500,stock:10,image:'croissant',cat:'베이커리',desc:'바삭한 크루아상에 달콤한 오후 한 조각 🍓',allergens:['밀','우유','계란'],likes:28,time:'09:30'},{id:2,shop:'cafe',name:'아메리카노',price:3000,stock:30,image:'coffee',cat:'커피·음료',desc:'오늘의 원두는 고소하고 부드럽게 내렸어요 ☕',coffee:true,allergens:[],likes:36,time:'09:25'},{id:3,shop:'rice',name:'소담 채소 덮밥',price:8500,stock:15,image:'rice',cat:'든든한 한 끼',desc:'채소 듬뿍, 골목에서 만나는 든든한 한 끼.',allergens:['대두'],likes:19,time:'09:20'},{id:4,shop:'bake',name:'버터 스콘',price:3500,stock:12,image:'scone',cat:'베이커리',desc:'겉은 바삭, 속은 촉촉. 오늘 아침 구웠어요.',allergens:['밀','우유','계란'],likes:21,time:'09:15'},{id:5,shop:'cafe',name:'오렌지 주스',price:4000,stock:20,image:'orange',cat:'커피·음료',desc:'커피 대신 상큼함이 필요한 날에 🍊',allergens:[],likes:16,time:'09:10'},{id:6,shop:'rice',name:'꼬마 주먹밥',price:2000,stock:24,image:'onigiri',cat:'든든한 한 끼',desc:'산책길에 쏙, 아이와 나누기 좋은 주먹밥.',allergens:['참깨'],likes:25,time:'09:05'},{id:7,shop:'bake',name:'오늘의 샌드위치',price:6500,stock:8,image:'sandwich',cat:'베이커리',desc:'싱싱한 채소를 넉넉하게 채웠어요.',allergens:['밀','우유','계란'],likes:32,time:'09:00'},{id:8,shop:'cafe',name:'카페라테',price:4500,stock:25,image:'latte',cat:'커피·음료',desc:'고소한 우유와 부드러운 에스프레소.',coffee:true,allergens:['우유'],likes:24,time:'08:55'},{id:9,shop:'rice',name:'에그 샐러드',price:5500,stock:10,image:'egg',cat:'든든한 한 끼',desc:'가벼운 한 끼도 정성 가득하게.',allergens:['계란'],likes:12,time:'08:50'}].map(m=>({...m,date:today(),image:`assets/${m.image}.jpg`}));
let savedState;try{savedState=JSON.parse(localStorage.getItem('hangolmok-v1')||'null')}catch{}
let state=savedState?.date===today()?savedState:{date:today(),menus:seed,liked:[],saved:[],setCount:0,pickups:[],result:null,request:null,large:false};
let page='feed',category='전체',shopFilter='',query='',reverse=false,draft=null,photo=null;
const persist=()=>{try{localStorage.setItem('hangolmok-v1',JSON.stringify(state))}catch{toast('저장 공간이 부족해 이번 화면에서만 유지됩니다.')}};
const menus=()=>state.menus.filter(m=>m.date===today());
const getShop=id=>shops.find(s=>s.id===id)||shops[0];
const imageSrc=m=>esc(m.image||'assets/croissant.jpg');
const logo=()=>`<button class="logo" data-action="nav" data-value="feed" aria-label="한 골목 한 메뉴 홈"><span class="logo-mark">ㅎ</span><span>한 골목, 한 메뉴<small>ONE ALLEY, EVERYDAY</small></span></button>`;
const navItems=[['feed','home','오늘의 골목'],['search','search','골목 둘러보기'],['set','sparkles','나의 골목 세트'],['saved','bookmark','저장한 메뉴']];
function nav(){return navItems.map(([p,i,t])=>`<button class="nav-button ${page===p?'active':''}" data-action="nav" data-value="${p}">${I(i)}${t}${p==='set'?'<span class="count">'+(state.result?1:0)+'</span>':''}</button>`).join('')}
function render(){document.body.classList.toggle('large-text',!!state.large);document.getElementById('app').innerHTML=`<div class="layout"><aside class="sidebar">${logo()}<div class="side-label">YOUR NEIGHBORHOOD</div><nav class="nav-list">${nav()}</nav><button class="create-btn" data-action="register">${I('plus')}오늘 메뉴 올리기</button><div class="side-bottom"><div class="public-note"><strong>${I('leaf').replace('<svg','<svg style="width:14px;height:14px;vertical-align:middle"')} 골목과 함께, 수수료 0원</strong>작은 가게의 오늘이 모이는 곳.<br>우리 동네를 걸어서 만나보세요.</div><button class="profile" data-action="settings"><span class="avatar">산</span><span><b>골목 산책자</b><small>오늘도 맛있는 산책</small></span><span style="margin-left:auto">${I('settings')}</span></button></div></aside><div class="workspace"><div class="mobile-header">${logo()}<div class="top-actions"><button class="location" data-action="location">${I('pin')}성수동${I('down')}</button><button class="icon-btn" data-action="settings" aria-label="설정">${I('settings')}</button></div></div><header class="topbar"><button class="location" data-action="location">${I('pin')}서울 성동구, 성수동 ${I('down')}</button><div class="top-actions"><span class="demo-badge">MVP PREVIEW</span><button class="icon-btn" data-action="notice" aria-label="이용 안내">${I('bell')}</button><span class="avatar" style="width:29px;height:29px;font-size:11px">산</span></div></header><div class="main-columns"><main class="feed">${mainContent()}</main>${rail()}</div></div></div><nav class="bottom-nav" aria-label="주 메뉴"><button class="${page==='feed'?'active':''}" data-action="nav" data-value="feed">${I('home')}골목 피드</button><button class="${page==='search'?'active':''}" data-action="nav" data-value="search">${I('search')}둘러보기</button><button data-action="register" aria-label="오늘 메뉴 올리기"><span class="plus-nav">${I('plus')}</span>메뉴 등록</button><button class="${page==='set'||page==='route'?'active':''}" data-action="nav" data-value="set">${I('sparkles')}골목 세트</button><button class="${page==='saved'?'active':''}" data-action="nav" data-value="saved">${I('bookmark')}저장함</button></nav>`;}
function rail(){return `<aside class="right-rail"><div class="rail-heading">${I('sparkles')}골목의 맛을 함께 담아요</div><div class="set-promo"><span class="mini-label">YOUR LITTLE ALLEY SET</span><h2>서울숲 가는 길,<br>같이 담아볼까요?</h2><p>인원과 예산만 알려주세요.<br>오늘 메뉴로 딱 맞는 세트를 찾아드려요.</p><div class="route-art"><svg viewBox="0 0 240 120"><path d="M35 34C70 20 65 100 119 85S163 10 209 30"/></svg><img class="route-bubble b1" src="assets/croissant.jpg" alt="크루아상"><img class="route-bubble b2" src="assets/coffee.jpg" alt="커피"><img class="route-bubble b3" src="assets/onigiri.jpg" alt="주먹밥"></div><button class="primary" data-action="request">${I('sparkles')}나만의 골목 세트 만들기 ${I('arrow')}</button><div class="promo-foot">오늘 올라온 메뉴만 · 예산 안에서 · 걸어서 픽업</div></div><div class="rail-section"><div class="rail-title"><h3>오늘 문을 연 이웃</h3><span>가상 가게 3곳</span></div>${shops.map(s=>`<div class="alley-row"><img src="assets/${s.image}.jpg" alt="${s.name}"><div><strong>${s.name}</strong><p>${menus().filter(m=>m.shop===s.id&&m.stock>0).length}개의 오늘 메뉴 · 성수 골목</p></div><button data-action="shop" data-value="${s.id}">구경</button></div>`).join('')}</div><div class="walk-note">${I('walk')}<div><strong>맛있는 산책, 가벼운 발걸음</strong><p>작은 가게를 잇는 도보 픽업.<br>골목의 새로운 단골이 되어주세요.</p></div></div><div class="rail-footer">성수 골목을 위한 공공 서비스 콘셉트<br>가상 가게 · 샘플 사진 · 이 기기에만 저장되는 데모<br><button data-action="admin">관리자 현황</button> · <button data-action="owner">사장님 메뉴 관리</button> · <button data-action="settings">접근성 설정</button><br>© 2026 한 골목, 한 메뉴</div></aside>`}
function mainContent(){if(page==='set')return setPage();if(page==='route')return routePage();if(page==='owner')return ownerPage();if(page==='admin')return adminPage();if(page==='search')return searchPage();if(page==='saved')return savedPage();return feedPage()}
function feedPage(){const d=new Date();const date=new Intl.DateTimeFormat('en-US',{month:'short',day:'2-digit',timeZone:'Asia/Seoul'}).format(d).toUpperCase();const weekday=new Intl.DateTimeFormat('en-US',{weekday:'long',timeZone:'Asia/Seoul'}).format(d).toUpperCase();return `<section class="intro"><div class="eyebrow"><span class="dot"></span>FRESH FROM OUR ALLEY</div><h1>오늘, 이 골목의<br><span class="accent">맛있는 순간.</span></h1><p>작은 가게의 오늘을 만나고, 나만의 세트로 즐겨요.</p><div class="date"><strong>${date}</strong><span>${weekday}</span><br>매일 새로 만나는 골목</div></section><div class="stories"><button class="story ${!shopFilter?'active':''}" data-action="shop" data-value=""><div class="story-ring"><div class="story-all">${I('grid')}</div></div><span>골목 전체</span><small>오늘의 모든 메뉴</small></button>${shops.map(s=>`<button class="story ${shopFilter===s.id?'active':''}" data-action="shop" data-value="${s.id}"><div class="story-ring"><img src="assets/${s.image}.jpg" alt=""></div><span>${s.name}</span><small>${menus().filter(m=>m.shop===s.id&&m.stock>0).length}개 메뉴 · 오늘</small></button>`).join('')}</div><div class="mobile-cta">${I('sparkles')}<div><strong>골목의 맛을 함께 담아요</strong><small>인원·예산에 맞는 오늘의 세트</small></div><button data-action="request">만들기 ↗</button></div><div class="feed-controls"><div class="chips">${['전체','베이커리','커피·음료','든든한 한 끼'].map(c=>`<button class="chip ${category===c?'active':''}" data-action="category" data-value="${c}">${c==='전체'?'오늘의 메뉴':c}</button>`).join('')}</div><button class="sort" data-action="sort">${reverse?'오래된순':'최신순'}${I('down')}</button></div><div class="posts">${filtered().map(post).join('')||empty('오늘의 메뉴를 준비 중이에요','다른 가게나 카테고리를 둘러보세요.')}</div><div class="feed-end">${I('leaf')}<br>오늘의 메뉴, 오늘의 골목.<br>가상 메뉴 ${menus().length}개 · 가격·재고는 데모 데이터입니다.</div>`}
function filtered(){let ms=menus().filter(m=>(!shopFilter||m.shop===shopFilter)&&(category==='전체'||m.cat===category));if(reverse)ms=ms.slice().reverse();return ms}
function post(m){const s=getShop(m.shop);return `<article class="post"><header class="post-header"><img src="assets/${s.image}.jpg" alt=""><div class="post-store">${s.name}<small>성수동 골목 · 오늘 ${esc(m.time)}</small></div>${I('pin')}</header><div class="photo" role="button" tabindex="0" data-action="detail" data-id="${m.id}" aria-label="${esc(m.name)} 상세 보기"><img src="${imageSrc(m)}" alt="${esc(m.name)} 샘플 사진" loading="lazy"><span class="photo-label"><span class="dot"></span>${m.stock?'오늘 준비했어요':'오늘은 품절이에요'}</span><div class="photo-bottom"><span>${I('walk')} 성수 골목에서 만나요</span><span>${m.stock?`남은 수량 ${m.stock}개`:'SOLD OUT'}</span></div></div><div class="post-actions"><button class="${state.liked.includes(m.id)?'liked':''}" data-action="like" data-id="${m.id}" aria-label="좋아요" aria-pressed="${state.liked.includes(m.id)}">${I('heart')}</button><span style="font-size:10px;color:#94998c">${m.likes+(state.liked.includes(m.id)?1:0)}</span><button data-action="detail" data-id="${m.id}" aria-label="메뉴 설명">${I('chat')}</button><button class="save ${state.saved.includes(m.id)?'saved':''}" data-action="save" data-id="${m.id}" aria-label="메뉴 저장" aria-pressed="${state.saved.includes(m.id)}">${I('bookmark')}</button></div><div class="post-info"><div class="title-price"><h3>${esc(m.name)}</h3><span class="price">${money(m.price)}</span></div><p>${esc(m.desc)}</p><div class="post-footer"><span>출처: ${m.custom?'사장님 확인 등록':'가상 가게 샘플'} · ${esc(m.time)}</span><button data-action="detail" data-id="${m.id}">메뉴 보기 ${I('chevron')}</button></div></div></article>`}
function empty(t,p,button=''){return `<div class="empty" style="grid-column:1/-1">${I('leaf')}<h3>${t}</h3><p>${p}</p>${button}</div>`}
function heading(t,p){return `<div class="section-heading"><div><div class="eyebrow"><span class="dot"></span>ONE ALLEY, EVERYDAY</div><h1>${t}</h1><p class="subtext">${p}</p></div></div>`}
function searchPage(){return heading('골목 둘러보기','오늘 만나고 싶은 메뉴를 찾아보세요.')+`<div class="searchbox">${I('search')}<input id="search" placeholder="메뉴 또는 가게 이름 검색" value="${esc(query)}" aria-label="메뉴 또는 가게 이름 검색"></div><div class="posts" id="search-results">${searchResults()}</div>`}
function searchResults(){return menus().filter(m=>(m.name+getShop(m.shop).name+m.cat).includes(query.trim())).map(post).join('')||empty('검색 결과가 없어요','메뉴 이름이나 가게 이름을 다시 확인해 주세요.')}
function savedPage(){return heading('저장한 메뉴','다음 산책에 만나고 싶은 맛있는 순간들.')+`<div class="posts">${menus().filter(m=>state.saved.includes(m.id)).map(post).join('')||empty('아직 저장한 메뉴가 없어요','마음에 드는 메뉴의 북마크를 눌러보세요.',`<button class="primary" data-action="nav" data-value="feed">오늘의 메뉴 보러 가기</button>`)}</div>`}
function requestForm(){const r=state.request||{people:2,budget:20000,purpose:'서울숲 가는 길',noCoffee:false,child:false,allergen:''};return `<form id="set-form"><div class="section-block"><h3>어떤 산책을 준비하시나요?</h3><p class="subtext" style="margin-bottom:20px">오늘 올라온 메뉴로 예산 안에서 조합해요.</p><div class="form-grid"><label class="field">함께할 인원<select name="people">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${r.people==n?'selected':''}>${n}명</option>`).join('')}</select></label><label class="field">전체 예산 (원)<input name="budget" type="number" min="1000" max="500000" step="500" required value="${r.budget}"></label><label class="field wide">오늘의 목적<select name="purpose">${['서울숲 가는 길','가벼운 간식 산책','든든한 한 끼'].map(s=>`<option ${r.purpose===s?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="checks"><label><input type="checkbox" name="child" ${r.child?'checked':''}>아이와 함께</label><label><input type="checkbox" name="noCoffee" ${r.noCoffee?'checked':''}>커피 제외</label></div><label class="field">제외할 알레르기 성분<select name="allergen"><option value="">선택 안 함</option>${['밀','우유','계란','대두','참깨'].map(a=>`<option ${r.allergen===a?'selected':''}>${a}</option>`).join('')}</select></label><p class="hint">아이 동반을 선택하면 커피를 제외해요. 알레르기는 등록된 성분으로만 필터링하며, 교차 접촉 여부는 가게에 확인해 주세요.</p></div><button class="primary" type="submit">${I('sparkles')}오늘의 골목 세트 찾기 ${I('arrow')}</button><p class="hint">실제 AI 연결 전, 확인된 가격·수량으로 계산하는 데모입니다.<br>1인당 음식과 음료를 각 1개씩 담고 예산이 남으면 다른 가게 메뉴도 살펴봐요.</p></form>`}
function combo(request,ms=menus()){const n=Number(request.people),budget=Number(request.budget);const valid=ms.filter(m=>m.stock>=n&&!(request.noCoffee||request.child?m.coffee:false)&&(!request.allergen||!m.allergens.includes(request.allergen)));const drinks=valid.filter(m=>m.cat==='커피·음료');let foods=valid.filter(m=>m.cat!=='커피·음료');if(request.purpose==='든든한 한 끼')foods=foods.filter(m=>m.shop==='rice'&&m.name!=='꼬마 주먹밥');if(request.purpose==='가벼운 간식 산책')foods=foods.filter(m=>m.cat==='베이커리');let candidates=[];for(const f of foods)for(const d of drinks){const base=[f,d];const total=(f.price+d.price)*n;if(total<=budget)candidates.push({items:base,total,score:200+total/budget*50});for(const e of valid.filter(m=>m.id!==f.id&&m.id!==d.id&&m.cat!=='커피·음료'&&m.shop!==f.shop)){const ts=total+e.price*n;if(ts<=budget)candidates.push({items:[...base,e],total:ts,score:new Set([f.shop,d.shop,e.shop]).size*100+ts/budget*50+(f.name==='딸기 크루아상'?5:0)})}}candidates.sort((a,b)=>b.score-a.score);if(!candidates.length)return null;const b=candidates[0];return {items:b.items.map(m=>({id:m.id,qty:n})),total:b.total,date:today()}}
function solve(r){state.request=r;state.result=combo(r);if(state.result)state.setCount++;state.pickups=[];persist()}
function invalidResult(){if(!state.result)return false;return state.result.date!==today()||state.result.items.some(i=>{const m=menus().find(m=>m.id===i.id);return !m||m.stock<i.qty})}
function resultList(){return state.result.items.map(i=>{const m=menus().find(m=>m.id===i.id);return `<div class="result-item"><img src="${imageSrc(m)}" alt="${esc(m.name)}"><div><strong>${esc(m.name)} × ${i.qty}</strong><small>${getShop(m.shop).name} · 남은 ${m.stock}개</small></div><div class="amount">${money(m.price*i.qty)}<small>개당 ${money(m.price)}</small></div></div>`}).join('')}
function setPage(){let intro=heading('나의 골목 세트','오늘의 메뉴를 모아, 나만의 맛있는 산책.');if(!state.request)return intro+requestForm();if(invalidResult()){state.result=combo(state.request);state.pickups=[];persist()}if(!state.result)return intro+empty('조건에 맞는 세트가 없어요','예산을 늘리거나 인원·제외 조건을 바꿔보세요.<br>품절 메뉴는 세트에 포함하지 않아요.',`<button class="primary" data-action="request">조건 바꿔서 다시 찾기</button>`)+`<p class="hint">요청: ${state.request.people}명 · ${money(state.request.budget)} · ${esc(state.request.purpose)}</p>`;return intro+`<div class="result-head"><div class="eyebrow">YOUR ALLEY SET</div><h3>${esc(state.request.purpose)}, 준비됐어요.</h3><p>${state.request.people}명 · 예산 ${money(state.request.budget)}${state.request.noCoffee||state.request.child?' · 커피 제외':''}${state.request.child?' · 아이 동반':''}${state.request.allergen?' · '+esc(state.request.allergen)+' 제외':''}<br>오늘 확인된 메뉴 ${state.result.items.length}개로 함께 즐겨요.</p></div><div class="section-block">${resultList()}<div class="total"><span>전체 금액 <small>가게별 현장 확인</small></span><strong>${money(state.result.total)}</strong></div><button class="primary" data-action="route">${I('walk')}도보 픽업 순서 보기 ${I('arrow')}</button><div class="actions-row"><button class="secondary" data-action="request">조건 바꾸기</button><button class="secondary" data-action="child">아이 있어요, 커피 빼줘</button></div><p class="hint">세트 구성은 예약이 아니에요. 재고는 방문 시 가게에 확인해 주세요.<br>결제는 포함하지 않으며 가게별 금액만 안내합니다.</p></div>`}
const distance=(a,b)=>{const r=Math.PI/180,x=(b.lat-a.lat)*r,y=(b.lng-a.lng)*r;const z=Math.sin(x/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(y/2)**2;return 6371000*2*Math.atan2(Math.sqrt(z),Math.sqrt(1-z))};
function routeData(){const ids=[...new Set(state.result.items.map(i=>getShop(menus().find(m=>m.id===i.id).shop).id))];let left=shops.filter(s=>ids.includes(s.id)),pos={lat:37.5446,lng:127.0445},out=[],total=0;while(left.length){left.sort((a,b)=>distance(pos,a)-distance(pos,b));const s=left.shift();const d=distance(pos,s);total+=d;out.push({...s,d});pos=s}return {shops:out,total}}
function routePage(){if(!state.result||invalidResult()){page='set';return setPage()}const route=routeData();return heading('맛있는 산책의 순서','성수역 부근 가상 출발점 → 골목 가게들')+`<div class="result-head"><h3>${route.shops.length}곳을 잇는 골목 산책</h3><p>직선 거리 합계 약 ${Math.ceil(route.total/10)*10}m · 계산상 약 ${Math.max(1,Math.ceil(route.total/70))}분<br>가상 좌표 기준 순서 예시 · 실제 보행 경로와 달라요.</p></div><div class="route-map" role="img" aria-label="가상 가게의 픽업 순서 예시"><svg class="map-path" viewBox="0 0 450 165"><path d="M50 120 155 55 280 110 390 45"/></svg>${route.shops.map((s,i)=>`<div class="map-pin" style="left:${20+i*28}%;top:${i%2?60:23}%">${i+1}</div>`).join('')}<span class="map-label">실제 지도가 아닌 동선 예시</span></div><div class="section-block">${route.shops.map((s,i)=>{const items=state.result.items.filter(x=>menus().find(m=>m.id===x.id).shop===s.id);const cost=items.reduce((a,x)=>a+menus().find(m=>m.id===x.id).price*x.qty,0);return `<div class="step"><span class="step-no">${state.pickups.includes(s.id)?'✓':i+1}</span><div class="step-content"><h3>${s.name} <span style="float:right;font-size:13px">${money(cost)}</span></h3><p>${s.address}<br>${items.map(x=>esc(menus().find(m=>m.id===x.id).name)+' × '+x.qty).join(' · ')}<br>이전 지점에서 직선 약 ${Math.ceil(s.d/10)*10}m</p><button class="secondary" data-action="pickup" data-value="${s.id}">${state.pickups.includes(s.id)?I('check')+' 수령 표시 완료':'가게에 보여줄 큰 글씨 화면'}</button></div></div>`}).join('')}<p class="hint">픽업 화면은 메뉴 확인용입니다. 주문·예약·결제가 전송되지 않습니다.</p><div class="actions-row"><button class="secondary voice" data-action="speak">${I('volume')}음성 안내</button><button class="secondary" data-action="nav" data-value="set">세트 다시 보기</button></div></div>`}
function ownerPage(){return heading('사장님의 오늘','사진 한 장, 짧은 말 한마디로 시작해요.')+`<button class="primary" data-action="register">${I('plus')}오늘 메뉴 올리기</button><div class="section-block" style="margin-top:20px"><h3>오늘 메뉴 · ${menus().length}개</h3><p class="hint">데모에서는 모든 가게의 메뉴를 관리할 수 있어요.</p>${menus().map(m=>`<div class="manage-row"><img src="${imageSrc(m)}" alt=""><div><strong>${esc(m.name)}</strong><small>${getShop(m.shop).name} · ${money(m.price)} · ${m.stock?m.stock+'개 남음':'품절'}</small></div><button data-action="stock" data-id="${m.id}">${m.stock?'품절로 바꾸기':'재고 다시 등록'}</button></div>`).join('')}</div>`}
function adminPage(){return heading('오늘 골목의 현황','가상 데이터로 보는 성수 골목의 오늘')+`<div class="stat-grid"><div class="stat"><small>오늘 등록된 메뉴</small><strong>${menus().length}<em> 개</em></strong></div><div class="stat"><small>판매 가능한 메뉴</small><strong>${menus().filter(m=>m.stock>0).length}<em> 개</em></strong></div><div class="stat"><small>세트 구성 횟수</small><strong>${state.setCount}<em> 회</em></strong></div></div><div class="section-block" style="margin-top:20px"><h3>가게별 오늘의 메뉴</h3>${shops.map(s=>{const n=menus().filter(m=>m.shop===s.id).length;return `<div class="bar-row"><span>${s.name}</span><div class="bar"><i style="width:${n/Math.max(...shops.map(sh=>menus().filter(m=>m.shop===sh.id).length))*100}%"></i></div><b>${n}개</b></div>`}).join('')}<p class="hint">기기에서 만든 세트 횟수입니다. 주문·매출 통계가 아닙니다.<br>공공데이터 API와 연결되지 않은 MVP 현황 화면입니다.</p></div><div class="section-block"><h3>골목 운영 메모</h3><p class="notes">가상 가게 3곳 · 성수 골목 1곳<br>오늘 메뉴가 없는 가게 ${shops.filter(s=>!menus().some(m=>m.shop===s.id&&m.stock>0)).length}곳<br>등록 시각과 사장님이 확인한 가격·재고만 표시합니다.</p></div>`}
let previousFocus;
function modal(title,body){previousFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-top"><h2 id="modal-title">${title}</h2><button data-action="close" aria-label="닫기">${I('close')}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';document.querySelector('.modal button,.modal input,.modal select')?.focus()}
function closeModal(){document.getElementById('overlay').innerHTML='';document.body.style.overflow='';previousFocus?.focus()}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
function detail(id){const m=menus().find(x=>x.id===id);if(!m)return;modal(esc(m.name),`<img class="detail-img" src="${imageSrc(m)}" alt="${esc(m.name)}"><div class="mini-label">${getShop(m.shop).name} · 오늘 ${esc(m.time)}</div><div class="big-price">${money(m.price)}</div><p class="subtext">${esc(m.desc)}</p><div class="tag-list"><span class="tag">${m.stock?m.stock+'개 남음':'품절'}</span><span class="tag">${m.cat}</span>${m.allergens.map(a=>`<span class="tag">${esc(a)} 함유</span>`).join('')}</div><p class="hint">출처: ${m.custom?'사장님 확인 등록':'가상 가게 샘플'} · ${esc(m.date)} ${esc(m.time)}<br>${m.custom?'직접 등록한 메뉴입니다.':'사진은 메뉴 분위기를 보여주는 샘플입니다.'}<br>알레르기와 실제 재고는 가게에 확인해 주세요.</p><button class="primary" style="margin-top:20px" data-action="request" ${!m.stock?'disabled':''}>${I('sparkles')}이 골목의 메뉴로 세트 만들기</button>`)}
function register(){draft=null;photo=null;modal('사장님의 오늘을 올려주세요',`<form id="draft-form"><label class="field" style="margin-bottom:15px">우리 가게<select name="shop">${shops.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></label><label class="upload"><div id="photo-preview">${I('camera')}<strong>음식 사진 한 장 올리기</strong><small>사진 선택 · JPG, PNG, WebP · 최대 5MB</small></div><input type="file" accept="image/jpeg,image/png,image/webp" id="photo-input" aria-label="음식 사진 선택" required></label><label class="field">오늘 메뉴를 짧게 알려주세요<textarea name="phrase" required placeholder="예: 딸기 크루아상 10개, 4,500원"></textarea></label><p class="hint">입력한 말에서 메뉴명·수량·가격을 읽는 규칙 기반 데모예요.<br>사진 인식은 연결 전입니다. 다음 화면에서 직접 확인해 주세요.</p><button class="primary" style="margin-top:18px" type="submit">큰 글씨로 초안 확인하기 ${I('arrow')}</button></form>`)}
function draftView(){modal('맞게 읽었나요?',`<form id="publish-form"><div class="draft-preview"><label>메뉴 이름<input name="name" required maxlength="35" value="${esc(draft.name)}"></label><div class="form-grid"><label>가격 (원)<input name="price" required min="100" max="500000" type="number" step="100" value="${draft.price}"></label><label>남은 수량<input name="stock" required min="1" max="999" type="number" value="${draft.stock}"></label></div></div><label class="field" style="margin-top:15px">메뉴 분류<select name="cat">${['베이커리','커피·음료','든든한 한 끼'].map(c=>`<option ${c===(draft.shop==='cafe'?'커피·음료':draft.shop==='rice'?'든든한 한 끼':'베이커리')?'selected':''}>${c}</option>`).join('')}</select></label><div class="checks">${['밀','우유','계란','대두','참깨'].map(a=>`<label><input type="checkbox" name="allergens" value="${a}">${a}</label>`).join('')}</div><label class="checks"><input name="coffee" type="checkbox">커피가 들어간 음료예요</label><p class="hint">해당하는 알레르기 성분을 선택해 주세요.<br>아래 버튼으로 확인한 뒤에만 오늘 피드에 게시됩니다.</p><button class="primary" type="submit">${I('check')}확인했어요, 오늘 메뉴 게시하기</button></form>`)}
function stockChange(id){const m=menus().find(x=>x.id===id);if(m.stock){m.stock=0;refreshSet();persist();render();toast('품절로 변경했어요. 세트도 다시 확인했어요.')}else modal('남은 수량을 알려주세요',`<form id="restock-form" data-id="${id}"><label class="field">${esc(m.name)}<input name="stock" type="number" min="1" max="999" required placeholder="직접 확인한 수량"></label><button class="primary" type="submit" style="margin-top:20px">확인한 수량으로 다시 등록</button></form>`)}
function refreshSet(){if(state.request&&invalidResult()){state.result=combo(state.request);state.pickups=[]}}
function pickup(shopId){if(invalidResult()){refreshSet();persist();closeModal();page='set';render();toast('메뉴가 바뀌어 세트를 다시 구성했어요.');return}const sh=getShop(shopId);const items=state.result.items.filter(i=>menus().find(m=>m.id===i.id).shop===shopId);modal('가게에 이 화면을 보여주세요',`<div class="pickup-card"><div class="pickup-title">${sh.name}</div><h2>메뉴 확인할게요</h2><p>${items.map(i=>esc(menus().find(m=>m.id===i.id).name)+'<br><b>'+i.qty+'개</b>').join('<br>')}</p><small>주문·예약·결제 내역이 아닌 메뉴 확인 화면입니다.<br>가게에서 재고와 결제 방법을 확인해 주세요.</small></div><button class="primary" style="margin-top:20px" data-action="received" data-value="${shopId}">${state.pickups.includes(shopId)?'수령 표시 완료':'수령했어요'}</button>`)}
function settings(){modal('산책자를 위한 설정',`<div class="switch-line"><div><strong>큰 글씨로 보기</strong><p class="subtext">메뉴와 안내 문구를 더 크게</p></div><button class="secondary" data-action="large" aria-pressed="${state.large}">${state.large?'켜짐':'꺼짐'}</button></div><div class="section-block" style="margin-top:12px"><h3>Easy English</h3><p class="english-note">Browse today's food → Build a set within your budget → Walk to each shop.<br>This is a demo. No reservation or payment is sent.</p><button class="secondary voice" style="margin-top:15px" data-action="english">${I('volume')}Listen in English</button></div><div class="more-row"><button class="secondary" data-action="owner">${I('shop')}사장님 메뉴 관리</button><button class="secondary" data-action="admin">${I('chart')}관리자 현황</button></div><p class="hint">현재 데이터는 이 브라우저에만 저장됩니다.<br>가상 가게와 샘플 메뉴를 사용하는 모바일 웹 MVP입니다.</p>`)}
function speak(text,lang='ko-KR'){if(!('speechSynthesis'in window)){toast('이 브라우저에서는 음성 안내를 지원하지 않아요.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=.9;speechSynthesis.speak(u)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b){if(e.target.classList.contains('modal-backdrop'))closeModal();return}const a=b.dataset.action,id=Number(b.dataset.id),v=b.dataset.value;if(a==='nav'){closeModal();page=v;render();window.scrollTo(0,0)}if(a==='shop'){page='feed';shopFilter=v;render()}if(a==='category'){category=v;render()}if(a==='sort'){reverse=!reverse;render()}if(a==='like'||a==='save'){const key=a==='like'?'liked':'saved';state[key]=state[key].includes(id)?state[key].filter(x=>x!==id):[...state[key],id];persist();render();if(a==='save')toast(state.saved.includes(id)?'다음 산책을 위해 저장했어요.':'저장함에서 꺼냈어요.')}if(a==='detail')detail(id);if(a==='close')closeModal();if(a==='request'){modal('나만의 골목 세트',requestForm())}if(a==='register')register();if(a==='owner'||a==='admin'){closeModal();page=a;render();window.scrollTo(0,0)}if(a==='stock')stockChange(id);if(a==='route'){closeModal();refreshSet();page=state.result?'route':'set';render();window.scrollTo(0,0)}if(a==='child'){solve({...state.request,child:true,noCoffee:true});render();toast(state.result?'아이와 함께 즐길 세트로 다시 담았어요.':'조건에 맞는 세트가 없어요. 예산을 바꿔보세요.')}if(a==='pickup')pickup(v);if(a==='received'){if(invalidResult()){refreshSet();persist();closeModal();page='set';render();toast('재고가 바뀌었어요. 세트를 확인해 주세요.');return}if(!state.pickups.includes(v))state.pickups.push(v);persist();closeModal();render();toast('이 기기에 수령 완료로 표시했어요.')}if(a==='settings')settings();if(a==='large'){state.large=!state.large;persist();render();settings()}if(a==='english')speak('Browse today’s food. Build a set within your budget. Walk to each shop. This is a demo. No reservation or payment is sent.','en-US');if(a==='speak'){const r=routeData();speak('오늘의 픽업 순서입니다. '+r.shops.map((s,i)=>`${i+1}번째, ${s.name}.`).join(' ')+'가상 좌표 기준 순서입니다. 실제 보행 경로를 확인해 주세요.')}if(a==='location')modal('지금은 성수 골목을 만나요',`<div class="section-block"><h3>서울 성동구 · 성수동</h3><p class="subtext">이번 MVP는 가상 가게 3곳과 오늘의 메뉴로 구성했어요. 새로운 골목은 다음에 만나요.</p></div><button class="primary" data-action="close">이 골목 둘러보기</button>`);if(a==='notice')modal('오늘의 골목 이용 안내',`<div class="notes">메뉴는 오늘 하루만 피드에 표시됩니다.<br>가상 가게 3곳과 샘플 사진을 사용합니다.<br>세트는 오늘의 가격과 재고로 계산합니다.<br>가게 방문 전 재고를 직접 확인해 주세요.<br>주문·예약·결제 기능은 포함하지 않습니다.<br>수수료 0원 공공 운영 서비스의 콘셉트 데모입니다.</div><button class="primary" style="margin-top:22px" data-action="close">알겠어요</button>`)});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.getElementById('search-results').innerHTML=searchResults()}});
document.addEventListener('change',e=>{if(e.target.id==='photo-input'){const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){e.target.value='';toast('5MB 이하의 JPG, PNG, WebP 사진을 선택해 주세요.');return}const reader=new FileReader();reader.onload=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,900/im.width);c.width=im.width*scale;c.height=im.height*scale;c.getContext('2d').drawImage(im,0,0,c.width,c.height);photo=c.toDataURL('image/jpeg',.78);document.getElementById('photo-preview').innerHTML=`<img src="${photo}" alt="선택한 음식 사진"><strong>사진을 골랐어요</strong>`};im.src=reader.result};reader.readAsDataURL(f)}});
document.addEventListener('submit',e=>{const f=e.target;if(!['set-form','draft-form','publish-form','restock-form'].includes(f.id))return;e.preventDefault();const fd=new FormData(f);if(f.id==='set-form'){const r={people:Number(fd.get('people')),budget:Number(fd.get('budget')),purpose:fd.get('purpose'),noCoffee:fd.has('noCoffee'),child:fd.has('child'),allergen:fd.get('allergen')};solve(r);closeModal();page='set';render();window.scrollTo(0,0)}if(f.id==='draft-form'){if(!photo){toast('메뉴 사진을 먼저 골라주세요.');return}const phrase=fd.get('phrase').trim(),pm=phrase.match(/([\d,]+)\s*원/),sm=phrase.match(/(\d+)\s*개/);if(!pm||!sm){toast('가격과 수량을 포함해 주세요. 예: 크루아상 10개, 4,500원');return}const name=phrase.replace(pm[0],'').replace(sm[0],'').replace(/[,，]/g,'').trim();if(!name){toast('메뉴 이름도 알려주세요.');return}draft={name,price:Number(pm[1].replace(/,/g,'')),stock:Number(sm[1]),shop:fd.get('shop'),desc:phrase,image:photo};draftView()}if(f.id==='publish-form'){const m={...draft,id:Date.now(),name:fd.get('name').trim(),price:Number(fd.get('price')),stock:Number(fd.get('stock')),cat:fd.get('cat'),allergens:fd.getAll('allergens'),coffee:fd.has('coffee'),date:today(),time:new Intl.DateTimeFormat('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Seoul'}).format(new Date()),likes:0,custom:true};if(!m.name)return;state.menus.unshift(m);persist();draft=null;photo=null;closeModal();page='feed';shopFilter='';category='전체';reverse=false;render();window.scrollTo(0,0);toast('확인한 메뉴가 오늘 피드에 올라왔어요.')}if(f.id==='restock-form'){const m=menus().find(m=>m.id===Number(f.dataset.id));m.stock=Number(fd.get('stock'));persist();closeModal();render();toast('확인한 수량으로 다시 등록했어요.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.key==='Enter'||e.key===' ')&&e.target.matches('.photo')){e.preventDefault();e.target.click()}if(e.key==='Tab'&&document.querySelector('.modal')){const els=[...document.querySelectorAll('.modal button:not([disabled]),.modal input,.modal select,.modal textarea')].filter(el=>el.offsetParent!==null);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});
window.addEventListener('storage',e=>{if(e.key==='hangolmok-v1'&&e.newValue){try{const next=JSON.parse(e.newValue);if(next.date===today()){state=next;refreshSet();render()}}catch{}}});
render();
